import { cpSync, existsSync, mkdirSync, readdirSync, rmSync } from "node:fs";
import { join, relative, sep } from "node:path";

export const APP_ROOT = join(import.meta.dirname, "..");
export const BACKUP_ROOT = join(APP_ROOT, "..", "..", "backups");
export const KEEP_BACKUPS = 30;

/** Regenerated by npm/next, or secrets that restore must never roll back. */
const SKIP_TOP = new Set([".env", ".next", ".stryker-tmp", "coverage", "node_modules", "out", "reports", "tsconfig.tsbuildinfo"]);

export function isSkipped(relPath: string): boolean {
  const parts = relPath.split(/[\\/]/).filter(Boolean);
  if (parts.length === 0) return false;
  if (SKIP_TOP.has(parts[0]!)) return true;
  return parts[0] === "content" && parts.length === 2 && parts[1]!.startsWith("audit.log");
}

const pad = (n: number) => String(n).padStart(2, "0");

export function backupName(date: Date, suffix = ""): string {
  const stamp = `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}_${pad(date.getHours())}-${pad(date.getMinutes())}-${pad(date.getSeconds())}`;
  return suffix ? `${stamp}_${suffix}` : stamp;
}

const NAME = /^\d{4}-\d{2}-\d{2}_\d{2}-\d{2}-\d{2}(?:_[\w-]+)?$/;

/** Oldest first; only folders created by this script. */
export function sortBackups(names: string[]): string[] {
  return names.filter((n) => NAME.test(n)).sort();
}

export function expiredBackups(names: string[], keep = KEEP_BACKUPS): string[] {
  const sorted = sortBackups(names);
  return sorted.slice(0, Math.max(0, sorted.length - keep));
}

export function listBackups(): string[] {
  if (!existsSync(BACKUP_ROOT)) return [];
  return sortBackups(readdirSync(BACKUP_ROOT, { withFileTypes: true }).filter((e) => e.isDirectory()).map((e) => e.name));
}

function pruneBackups() {
  for (const old of expiredBackups(listBackups())) rmSync(join(BACKUP_ROOT, old), { recursive: true, force: true });
}

function copyApp(suffix: string, now: Date): string {
  mkdirSync(BACKUP_ROOT, { recursive: true });
  let name = backupName(now, suffix);
  for (let i = 2; existsSync(join(BACKUP_ROOT, name)); i++) name = `${backupName(now, suffix)}-${i}`;
  const target = join(BACKUP_ROOT, name);
  cpSync(APP_ROOT, target, {
    recursive: true,
    filter: (src) => !isSkipped(relative(APP_ROOT, src)),
  });
  return name;
}

export function createBackup(suffix = "", now = new Date()): string {
  const name = copyApp(suffix, now);
  pruneBackups();
  return name;
}

export function restoreBackup(name: string): string {
  if (!NAME.test(name) || name.includes(sep) || name.includes("/")) throw new Error(`Некорректное имя копии: ${name}`);
  const source = join(BACKUP_ROOT, name);
  if (!existsSync(source)) throw new Error(`Копия не найдена: ${name}. Список: npm run restore`);

  // Pruning waits until the copy is done: the source may be the oldest backup.
  const safety = copyApp("pered-otkatom", new Date());
  for (const entry of readdirSync(APP_ROOT)) {
    if (!isSkipped(entry)) rmSync(join(APP_ROOT, entry), { recursive: true, force: true });
  }
  cpSync(source, APP_ROOT, { recursive: true });
  pruneBackups();
  return safety;
}
